cd /workspace && docker compose exec -T backend node -e '
(async () => {
  const r = await fetch("http://backend:4000/api/v1/swagger/swagger-ui-init.js");
  const txt = await r.text();
  console.log("create-one-teacher present:", txt.includes("/api/v1/teacher/create-one-teacher"));
  console.log("create-one-school present:", txt.includes("/api/v1/school/create-one-school"));

  // safe auth-enforcement checks (POST without/with wrong key -> expect 401/403, not 201)
  const body = JSON.stringify({ schoolSlug:"eckener-schule", emailAddress:"probe@x.de", role:"teacher", firstName:"P", lastName:"X" });
  const noKey = await fetch("http://backend:4000/api/v1/teacher/create-one-teacher", { method:"POST", headers:{"Content-Type":"application/json"}, body });
  console.log("create-one-teacher (NO key) HTTP", noKey.status, (await noKey.text()).slice(0,80));

  const badKey = await fetch("http://backend:4000/api/v1/teacher/create-one-teacher", { method:"POST", headers:{"Content-Type":"application/json","x-super-admin-api-key":"wrong-key-123"}, body });
  console.log("create-one-teacher (BAD key) HTTP", badKey.status, (await badKey.text()).slice(0,80));
})();
' 2>&1 | head -20
